def find_kth_sequence(n, k):
    def is_valid_sequence(seq):
        prefix_sums = [0]
        for num in seq:
            prefix_sums.append((prefix_sums[-1] + num) % n)
        for i in range(1, len(prefix_sums)):
            for j in range(i + 1, len(prefix_sums)):
                if prefix_sums[j] == prefix_sums[i]:
                    return False
        return True

    def generate_sequence(n, k):
        count = 0
        current_sequence = [0] * (n - 1)
        while True:
            if is_valid_sequence(current_sequence):
                count += 1
                if count == k:
                    return current_sequence
            current_sequence = next_sequence(current_sequence, n)

    def next_sequence(seq, n):
        for i in range(len(seq) - 1, -1, -1):
            if seq[i] < n - 1:
                seq[i] += 1
                for j in range(i + 1, len(seq)):
                    seq[j] = 1
                break
        return seq

    result = generate_sequence(n, k)
    return ' '.join(map(str, result))

